head.script:
scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// 공통 wframe 은 input 기준으로 작성되어 있어 searchbox 미지원 항목을 정리한다
//   - dataType 콤보(con_dataType, par_dataType) 에서 float, bigDecimal, euro, rupee, tenge 제거
//   - setDataType 미지원 → par_dataType, btn_setDataType 비활성화
//   - description/validation 을 searchbox 전용으로 덮어쓰기
scwin.wf_sample_onwframeload = function () {
    let unsupportedIdx = [9, 8, 7, 6, 3]; // tenge, rupee, euro, bigDecimal, float (역순)

    let conDataType = wf_sample.getObj("con_dataType");
    let parDataType = wf_sample.getObj("par_dataType");

    if (conDataType) {
        unsupportedIdx.forEach(function (idx) {
            conDataType.deleteItem(idx, true);
        });
    }
    if (parDataType) {
        unsupportedIdx.forEach(function (idx) {
            parDataType.deleteItem(idx, true);
        });
        parDataType.setDisabled(true);
    }
    let btnSetDataType = wf_sample.getObj("btn_setDataType");
    if (btnSetDataType) {
        btnSetDataType.setDisabled(true);
    }
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        dataType: wf_sample.getObj("con_dataType").getText(),
    }

    let cList = $c.gcm.createCList(properties)

    // comp 생성 함수 호출
    await $c.gcm.createBasicSearchBox(cList);
}
